function clean(v){return String(v===undefined||v===null?'':v).trim()}
function isTrue(v){return ['TRUE','TAK','YES','1'].includes(clean(v).toUpperCase())}
function table(name,headers){let raw=[];try{raw=$(name).all().map(i=>i.json||{})}catch{return[]}
